tional_logic":null},{"visa_type":"JP_VISIT_JAPAN_WEB","field_name":"immigration_declaration","label":"I have reviewed the immigration declaration answers above and confirm that they are complete and truthful.","field_type":"computed","required":false,"step_number":3,"step_name":"Immigration Declaration","display_order":4,"placeholder":null,"validation_rules":{"label_zh":"旧版入境申报确认","official":true,"runner_canonical_key":"immigration_declaration","no_user_input":true,"legacy_compatibility_only":true,"replaced_by":"customs_declaration_confirmed","label_en":"I have reviewed the immigration declaration answers above and confirm that they are complete and truthful.","official_label_en":"I have reviewed the immigration declaration answers above and confirm that they are complete and truthful."},"options":null,"conditional_logic":{"showIf":"false"}},{"visa_type":"JP_VISIT_JAPAN_WEB","field_name":"final_declaration","label":"Final Declaration (derived from the official final confirmation)","field_type":"computed","required":false,"step_number":4,"step_name":"Customs Declaration","display_order":12,"placeholder":null,"validation_rules":{"label_zh":"最终申报（由官网最终确认生成）","official":true,"runner_canonical_key":"final_declaration","derived_from":["customs_declaration_confirmed"],"no_user_input":true,"aggregation":"yes_only_when_official_confirmation_is_true","label_en":"Final Declaration (derived from the official final confirmation)","official_label_en":"Final Declaration (derived from the official final confirmation)"},"options":null,"conditional_logic":{"showIf":"false"}}]$jp_vjw_fields$::jsonb) AS row(
    visa_type text,
    field_name text,
    label text,
    field_type text,
